package banking;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class BankAccount {
    private long balanceCents; // only this class can establish the invariant
    private final List<String> auditLog = new ArrayList<>();

    public BankAccount(long openingBalanceCents) {
        if (openingBalanceCents < 0) throw new IllegalArgumentException("negative opening");
        this.balanceCents = openingBalanceCents;
    }

    public synchronized void deposit(long cents) {
        if (cents <= 0) throw new IllegalArgumentException("cents must be positive");
        balanceCents += cents;
        auditLog.add("deposit:" + cents);
    }

    public synchronized long balanceCents() {
        return balanceCents;
    }

    // Deliberately NOT public List<String> getAuditLog().
    // Returning the live list would widen write access to everyone.
    public synchronized List<String> auditSnapshot() {
        return Collections.unmodifiableList(new ArrayList<>(auditLog));
    }

    // Package-private: ledger reconciliation lives in the same package
    // and needs batch access, but external clients must not call it.
    void applyLedgerAdjustment(long delta) {
        balanceCents += delta;
    }
}

package banking;

public class AccountBase {
    protected long balanceCents; // visible to subclasses, even cross-package
    protected void record(String event) { /* append to log */ }
}

// ---- different package ----
package lending;

import banking.AccountBase;

public class LoanAccount extends AccountBase {
    public void accrueInterest(long interest) {
        balanceCents += interest; // OK: access via inheritance (this.balanceCents)
        record("interest:" + interest); // OK: protected method via inheritance
    }

    public void auditOther(AccountBase other) {
        // other.balanceCents = 0; // COMPILE ERROR if uncommented:
        // cross-package protected access cannot go through an arbitrary base reference
        this.balanceCents = 0; // OK: through own inheritance chain
    }
}
